<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\UserGrantedClientScopes\Domain\Event;

use Override;
use Civi\Lughauth\Features\Access\UserGrantedClientScopes\Domain\UserGrantedClientScopes;
use Civi\Lughauth\Shared\Event\PublicEvent;

class UserGrantedClientScopesUpdateEvent extends UserGrantedClientScopesEvent implements PublicEvent
{
    public function __construct(
        UserGrantedClientScopes $payload,
        public readonly UserGrantedClientScopes $original
    ) {
        parent::__construct($payload);
    }
    #[Override]
    public function eventType(): string
    {
        return 'user-granted-client-scopes.update';
    }
    #[Override]
    public function schemaVersion(): string
    {
        return 'v1';
    }
    #[Override]
    public function payload(): array
    {
        return $this->payload->asPublicJson();
    }
    #[Override]
    public function original(): array
    {
        return $this->original->asPublicJson();
    }
}
